// Un élément par fil de discussion (une candidature = un fil)
const msgs = ($input.first().json.messages) || [];
const vus = new Set();
const out = [];
for (const m of msgs) { if (m.threadId && !vus.has(m.threadId)) { vus.add(m.threadId); out.push({ json: { threadId: m.threadId } }); } }
return out;

// Décide quelles candidatures relancer : envoyées il y a JOURS_AVANT_RELANCE jours ou plus, sans réponse, jamais relancées.
const cfg = $('Config').first().json;
const moi = String(cfg.EMAIL_MOI || '').toLowerCase();
const jours = Number(cfg.JOURS_AVANT_RELANCE) || 21;
const max = Number(cfg.MAX_RELANCES_PAR_JOUR) || 20;
const simulation = cfg.SIMULATION === true || String(cfg.SIMULATION).toLowerCase() === 'true';
const limite = Date.now() - jours * 24 * 3600 * 1000;

const entete = (m, nom) => {
  const h = ((m.payload && m.payload.headers) || []).find(x => String(x.name).toLowerCase() === nom.toLowerCase());
  return h ? String(h.value) : '';
};
const adresse = v => { const m = String(v).match(/<([^>]+)>/); return (m ? m[1] : String(v)).trim().toLowerCase(); };
const dateFr = ms => new Date(ms).toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Europe/Paris' });

const decisions = [];
for (const item of $input.all()) {
  const fil = item.json || {};
  const msgs = (fil.messages || []).slice().sort((a, b) => Number(a.internalDate) - Number(b.internalDate));
  if (!msgs.length) continue;
  const premier = msgs[0];
  const sujet = entete(premier, 'Subject');
  const dest = adresse(entete(premier, 'To'));
  const entreprise = sujet.split(' - ').slice(1).join(' - ').trim() || dest.split('@')[1] || '';
  const base = { threadId: fil.id, entreprise, destinataire: dest, sujet, envoye_le: dateFr(Number(premier.internalDate)) };
  const deMoi = msgs.filter(m => adresse(entete(m, 'From')) === moi);
  const autres = msgs.filter(m => adresse(entete(m, 'From')) !== moi);
  let statut = 'a_relancer';
  if (adresse(entete(premier, 'From')) !== moi) statut = 'ignore_pas_de_moi';
  else if (!dest || dest === moi) statut = 'ignore_test';
  else if (autres.some(m => /mailer-daemon|postmaster|no-?reply.*bounce/i.test(entete(m, 'From')))) statut = 'non_distribue';
  else if (autres.length) statut = 'a_repondu';
  else if (deMoi.length >= 2) statut = 'deja_relance';
  else if (Number(premier.internalDate) > limite) statut = 'trop_recent';
  decisions.push({ ...base, statut, message_id: entete(premier, 'Message-ID'), t: Number(premier.internalDate) });
}

const aRelancer = decisions.filter(d => d.statut === 'a_relancer').sort((a, b) => a.t - b.t).slice(0, max); // les plus anciennes d'abord
const compte = decisions.reduce((a, d) => (a[d.statut] = (a[d.statut] || 0) + 1, a), {});

// Message de relance (HTML), envoyé en réponse dans le même fil
const MOI = { prenom: 'Adam', nom: 'SOUFANE', tel: '+33 7 45 45 05 95', email: 'adamsouf2006@gmail.com',
  portfolio: 'https://portfolioadamsoufane.netlify.app/', linkedin: 'https://www.linkedin.com/in/adam-soufane-72aaa2366/' };
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
function corps(d) {
  const paras = [
    'Madame, Monsieur,',
    `Je me permets de revenir vers vous au sujet de ma candidature pour une alternance de Data Analyst (12 mois) au sein de ${d.entreprise}, que je vous ai adressée le ${d.envoye_le}.`,
    "Je reste très motivé à l'idée de rejoindre vos équipes. Si le poste ne relève pas de votre périmètre, pourriez-vous transmettre ma candidature à la personne en charge du recrutement ? Mon CV et ma lettre de motivation figurent dans le message ci-dessous.",
    'Je vous remercie par avance pour votre retour et reste disponible pour un échange.',
    'Bien cordialement,',
  ];
  return '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#222">' +
    paras.map(p => `<p style="margin:0 0 12px 0">${esc(p)}</p>`).join('') +
    `<p style="margin:0"><b>${MOI.prenom} ${MOI.nom}</b><br>${MOI.tel}<br><a href="mailto:${MOI.email}">${MOI.email}</a><br>` +
    `<a href="${MOI.portfolio}">Portfolio</a> · <a href="${MOI.linkedin}">LinkedIn</a></p></div>`;
}
const b64 = s => Buffer.from(s, 'utf8').toString('base64');
const b64url = s => Buffer.from(s, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const enteteUtf8 = s => `=?UTF-8?B?${b64(s)}?=`;
function mime(d) {
  const sujet = /^re\s*:/i.test(d.sujet) ? d.sujet : 'Re: ' + d.sujet;
  const lignes = [
    `From: ${enteteUtf8('Adam Soufane')} <${moi}>`,
    `To: ${d.destinataire}`,
    `Subject: ${enteteUtf8(sujet)}`,
    ...(d.message_id ? [`In-Reply-To: ${d.message_id}`, `References: ${d.message_id}`] : []),
    'MIME-Version: 1.0',
    'Content-Type: text/html; charset=UTF-8',
    'Content-Transfer-Encoding: base64',
    '',
    b64(corps(d)).replace(/(.{76})/g, '$1\r\n'),
  ];
  return b64url(lignes.join('\r\n'));
}

if (!aRelancer.length) return [{ json: { aucune: true, simulation, compte, jours } }];
return aRelancer.map(d => ({ json: { ...d, simulation, compte, jours, raw: mime(d) } }));

// Récapitulatif des relances envoyées (ou simulées)
const cfg = $('Config').first().json;
const lignes = $('À relancer ?').all().map(i => i.json);
const premier = lignes[0] || {};
const envois = $input.all().map(i => i.json || {});
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const LIB = { a_repondu: 'ont répondu', deja_relance: 'déjà relancées', trop_recent: 'trop récentes', non_distribue: 'non distribuées', ignore_test: 'mails de test', ignore_pas_de_moi: 'autres' };
const faits = premier.aucune ? [] : lignes.map((l, i) => ({ ...l, ok: premier.simulation ? null : !!(envois[i] && envois[i].id && !envois[i].error) }));
const titre = premier.simulation ? `[SIMULATION] ${faits.length} relance(s) qui seraient envoyées` : `${faits.filter(f => f.ok).length} relance(s) envoyée(s)`;
const tableau = faits.length ? '<table style="border-collapse:collapse;font-size:13px"><tr><th style="padding:4px 8px;border:1px solid #ccc">Entreprise</th><th style="padding:4px 8px;border:1px solid #ccc">Destinataire</th><th style="padding:4px 8px;border:1px solid #ccc">Candidature du</th><th style="padding:4px 8px;border:1px solid #ccc">Relance</th></tr>' +
  faits.map(f => `<tr><td style="padding:4px 8px;border:1px solid #ccc">${esc(f.entreprise)}</td><td style="padding:4px 8px;border:1px solid #ccc">${esc(f.destinataire)}</td><td style="padding:4px 8px;border:1px solid #ccc">${esc(f.envoye_le)}</td><td style="padding:4px 8px;border:1px solid #ccc">${f.ok === null ? 'simulée' : f.ok ? 'envoyée' : 'échec'}</td></tr>`).join('') + '</table>' : '<p>Aucune candidature à relancer aujourd\'hui.</p>';
const autres = Object.entries(premier.compte || {}).filter(([k]) => k !== 'a_relancer').map(([k, v]) => `${v} ${LIB[k] || k}`).join(' · ');
const html = `<div style="font-family:Arial,sans-serif;font-size:14px"><p><b>${esc(titre)}</b></p>${tableau}<p>Candidatures de plus de ${esc(premier.jours)} jours examinées${autres ? ' — ' + esc(autres) : ''}.</p></div>`;
const jour = new Date().toISOString().slice(0, 10);
return [{ json: { destinataire: cfg.EMAIL_MOI, objet: `${premier.simulation ? '[SIMULATION] ' : ''}Récap relances alternance – ${jour} – ${faits.filter(f => f.ok !== false).length}`, html } }];
